export const getSubmitPracticeUrl = (id: string,) => {




  return `/api/practice/${id}/submit`
}

export const submitPractice = async (id: string,
    practiceAnswers: PracticeAnswers, options?: Parameters<typeof customFetch>[1]): Promise<PracticeAttempt> => {

    const getHeaders = (h?: NonNullable<RequestInit['headers']>): Record<string, string | readonly string[]> => {
    if (!h) return {};
    if (h instanceof Headers) return Object.fromEntries(h.entries());
    if (Symbol.iterator in h) {
      return Object.fromEntries(
        Array.from(h as Iterable<Iterable<string>>, (entry) => Array.from(entry) as [string, string]),
      );
    }
    const headers: Record<string, string | readonly string[]> = {};
    for (const [name, value] of Object.entries<string | readonly string[] | undefined>(h)) {
      if (value !== undefined) headers[name] = value;
    }
    return headers;
  };
return customFetch<PracticeAttempt>(getSubmitPracticeUrl(id),
  {
    ...options,
    method: 'POST',
    headers: { 'Content-Type': 'application/json', ...getHeaders(options?.headers) },
    body: JSON.stringify(practiceAnswers)
  }
);}





export const getSubmitPracticeMutationKey = () => ['submitPractice'] as const;

export const getSubmitPracticeMutationOptions = <TError = ErrorType<unknown>,
    TContext = unknown>(options?: { mutation?:UseMutationOptions<Awaited<ReturnType<typeof submitPractice>>, TError,SubmitPracticeMutationVariables, TContext>, request?: SecondParameter<typeof customFetch>}
): UseMutationOptions<Awaited<ReturnType<typeof submitPractice>>, TError,SubmitPracticeMutationVariables, TContext> => {

const mutationKey = getSubmitPracticeMutationKey();
const {mutation: mutationOptions, request: requestOptions} = options ?
      options.mutation && 'mutationKey' in options.mutation && options.mutation.mutationKey ?
      options
      : {...options, mutation: {...options.mutation, mutationKey}}
      : {mutation: { mutationKey, }, request: undefined};




      const mutationFn: MutationFunction<Awaited<ReturnType<typeof submitPractice>>, SubmitPracticeMutationVariables> = (props) => {
          const {id,data} = props ?? {};

          return  submitPractice(id,data,requestOptions)
        }






  return  { mutationFn, ...mutationOptions }}

    export type SubmitPracticeMutationResult = NonNullable<Awaited<ReturnType<typeof submitPractice>>>
    export type SubmitPracticeMutationBody = BodyType<PracticeAnswers>
    export type SubmitPracticeMutationError = ErrorType<unknown>
    export type SubmitPracticeMutationVariables = {id: string;data: BodyType<PracticeAnswers>}

    export const useSubmitPractice = <TError = ErrorType<unknown>,
    TContext = unknown>(options?: { mutation?:UseMutationOptions<Awaited<ReturnType<typeof submitPractice>>, TError,SubmitPracticeMutationVariables, TContext>, request?: SecondParameter<typeof customFetch>}
 , queryClient?: QueryClient): UseMutationResult<
        Awaited<ReturnType<typeof submitPractice>>,
        TError,
        SubmitPracticeMutationVariables,
        TContext
      > => {
      return useMutation(getSubmitPracticeMutationOptions(options), queryClient);
    }

